MOTIF_NAME = 'passed_pawn_protected'
MOTIF_DESCRIPTION = 'The side to move has a passed pawn that is defended by a friendly pawn, while the opponent has no such supported passed pawn.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    # Determine which ranks are the promotion direction for stm
    if stm == chess.WHITE:
        stm_pawn_dir = 1
        stm_promotion_rank = 7
        opp_pawn_dir = -1
        opp_promotion_rank = 0
    else:
        stm_pawn_dir = -1
        stm_promotion_rank = 0
        opp_pawn_dir = 1
        opp_promotion_rank = 7

    def is_passed(color, sq):
        """Check if the pawn on sq is a passed pawn (no opponent pawns blocking its path)."""
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            # Check ranks from r+1 to 7 on files f-1, f, f+1
            for check_file in (f-1, f, f+1):
                if 0 <= check_file <= 7:
                    for check_rank in range(r + 1, 8):
                        p = board.piece_at(chess.square(check_file, check_rank))
                        if p and p.piece_type == chess.PAWN and p.color != color:
                            return False
        else:
            for check_file in (f-1, f, f+1):
                if 0 <= check_file <= 7:
                    for check_rank in range(r - 1, -1, -1):
                        p = board.piece_at(chess.square(check_file, check_rank))
                        if p and p.piece_type == chess.PAWN and p.color != color:
                            return False
        return True

    def supported_by_friendly_pawn(color, sq):
        """Check if any friendly pawn defends this square directly."""
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            # Pawns defend from one rank below, diagonally
            if r > 0:
                for df in (-1, 1):
                    cf = f + df
                    if 0 <= cf <= 7:
                        defender = board.piece_at(chess.square(cf, r - 1))
                        if defender and defender.piece_type == chess.PAWN and defender.color == color:
                            return True
        else:
            if r < 7:
                for df in (-1, 1):
                    cf = f + df
                    if 0 <= cf <= 7:
                        defender = board.piece_at(chess.square(cf, r + 1))
                        if defender and defender.piece_type == chess.PAWN and defender.color == color:
                            return True
        return False

    stm_passed = 0
    opp_passed = 0

    for sq in chess.SQUARES:
        p = board.piece_at(sq)
        if not p or p.piece_type != chess.PAWN:
            continue
        if p.color == stm:
            if is_passed(stm, sq) and supported_by_friendly_pawn(stm, sq):
                stm_passed += 1
        else:
            if is_passed(opp, sq) and supported_by_friendly_pawn(opp, sq):
                opp_passed += 1

    return stm_passed > opp_passed
